-- tourism 도메인: 칸 대표 이미지 seed 적재(SPEC-0030 R9·R10).
--
-- planner가 산출한 landmarks-161-with-images.json에서 옮긴 365건이다. 칸당 1~4건이며
-- display_order 0이 대표다.
--
-- **원본 375건 중 17건은 사진이 다른 곳의 것이었다.** planner가 TourAPI를 이름으로 검색해
-- 첫 결과를 썼는데, "성산일출봉"에 성산흑돼지두루치기 성산일출봉점이, "불국사"에 불국사밀면이
-- 걸린 식이다(원본 JSON의 tour.title에 그 상호가 남아 있다). 375장을 전부 열어 확인한 뒤
-- 13건은 올바른 contentid의 이미지로 바꾸고, 대체할 사진이 없는 4건(함평 한우·의령 망개떡·
-- 운문사·동피랑 벽화마을)은 행을 지웠다. 지운 자리는 display_order를 당겨 메웠다.
--
-- **이어서 판정을 보류했던 37건도 다시 보아 30건을 손봤다.** 그 장소가 맞긴 하나 이름이
-- 가리키는 대상이 프레임에 없던 것들이다(관촉사에 은진미륵 대신 대웅전, 해인사 장경판전에
-- 해인사 전경). 24건은 갤러리에서 대상이 실제로 보이는 컷으로 바꾸고, 업스트림에 그런 사진이
-- 아예 없는 6건(영동 영국사 은행나무·청양 고추·구기자·칠갑산 도립공원·태안해안국립공원·
-- 영광 굴비·사선대)은 지웠다. 지운 뒤에도 161칸 모두 대표 이미지를 갖는다.
--
-- **칸 코드를 값으로 적지 않고 지역 이름으로 조인해 얻는다.** seed의 region은 '경기도 수원시'
-- 형태이고 칸 코드는 V74가 정하므로, 코드를 여기 베껴 두면 두 곳이 어긋날 수 있다. 조인이
-- 실패하면 아래 검증에서 기동이 막힌다.
--
-- **URL을 https로 맞춘다.** 원본 258건이 http였는데, 모바일 클라이언트가 평문 HTTP를 기본
-- 차단하므로 그대로 두면 이미지가 뜨지 않는다. 호스트는 동일하다.
--
-- **특산품(SPECIALTY) 14건은 아직 없다.** 확보되는 대로 별도 마이그레이션으로 적재하며,
-- 그 전까지 해당 칸도 조회에서 빠지지 않고 representativeImage만 null이다(R10).

CREATE TEMP TABLE map_cell_image_seed (
    region_label  varchar(128),
    display_order integer,
    image_url     varchar(500),
    thumbnail_url varchar(500),
    caption       varchar(255),
    kind          varchar(20),
    copyright     varchar(20),
    content_id    varchar(20)
) ON COMMIT DROP;

;

-- 지역 이름 → 칸 코드. 칸 이름은 map_cell이, 시도 이름은 area가 갖는다.
-- 광역시 칸은 이름 하나('서울특별시'), 그 외는 '시도 + 칸 이름'이다.
SELECT c.cell_id, s.display_order, s.image_url, s.thumbnail_url,
       s.caption, s.kind, s.copyright, s.content_id
FROM map_cell_image_seed s
JOIN (
    SELECT DISTINCT mc.id AS cell_id,
           CASE WHEN a.name_ko ~ '(광역시|특별시|특별자치시)$' THEN mc.name_ko
                ELSE a.name_ko || ' ' || mc.name_ko END AS region_label
    FROM tour.map_cell mc
    JOIN tour.map_cell_district mcd ON mcd.cell_id = mc.id
    JOIN tour.district d ON d.code = mcd.district_code
    JOIN tour.area a ON a.area_cd = d.area_cd
) c ON c.region_label = s.region_label;

-- **한 건도 유실되지 않아야 한다.** 조인이 어긋나면 그 칸만 조용히 이미지가 없어지고,
-- 그것은 "이미지가 없는 칸"(정상)과 구분되지 않는다.
DO $$
DECLARE
    seeded  integer;
    loaded  integer;
BEGIN
    SELECT count(*) INTO seeded FROM map_cell_image_seed;
    SELECT count(*) INTO loaded FROM tour.map_cell_image;
    IF seeded <> loaded THEN
        RAISE EXCEPTION 'seed % 건 중 % 건만 적재됐습니다 — 지역 이름 매칭을 확인하십시오', seeded, loaded;
    END IF;
END $$;
